import fs from 'node:fs';import net from 'node:net';import tls from 'node:tls';import http from 'node:http';import https from 'node:https';import dns from 'node:dns';import dgram from 'node:dgram';import cp from 'node:child_process';import dc from 'node:diagnostics_channel';import {syncBuiltinESMExports} from 'node:module';
await import(process.env.PELORA_DENIAL_PRELOAD_URL);
const log=process.env.PELORA_ATTEMPT_LOG,life=process.env.PELORA_LIFECYCLE_LOG; if(!log||!life)throw Error('attempt instrumentation configuration absent');let count=0;
function record(api){count++;fs.appendFileSync(log,JSON.stringify({api,pid:process.pid,entry:process.argv[1],phase:process.env.PELORA_ATTEMPT_PHASE})+'\n');}
function deny(api){return function(){record(api);throw Error('Network blocked for Task11D regression');};}
function wrap(o,k,label){if(typeof o[k]==='function')o[k]=deny(label||k);}
for(const [o,keys,prefix] of [[net,['connect','createConnection'],'net'],[net.Socket.prototype,['connect'],'Socket'],[tls,['connect'],'tls'],[http,['request','get'],'http'],[https,['request','get'],'https'],[http.Agent.prototype,['createConnection'],'http.Agent'],[https.Agent.prototype,['createConnection'],'https.Agent'],[dns,['lookup','lookupService','resolve','resolve4','resolve6','resolveAny','resolveCaa','resolveCname','resolveMx','resolveNaptr','resolveNs','resolvePtr','resolveSoa','resolveSrv','resolveTxt','reverse'],'dns'],[dns.promises,['lookup','lookupService','resolve','resolve4','resolve6','resolveAny','resolveCaa','resolveCname','resolveMx','resolveNaptr','resolveNs','resolvePtr','resolveSoa','resolveSrv','resolveTxt','reverse'],'dns.promises'],[dns.Resolver.prototype,['resolve','resolve4','resolve6','resolveAny','reverse'],'dns.Resolver'],[dns.promises.Resolver.prototype,['resolve','resolve4','resolve6','resolveAny','reverse'],'dns.promises.Resolver'],[dgram.Socket.prototype,['send','connect'],'dgram'],[cp,['exec','execFile','spawn','fork','execSync','execFileSync','spawnSync'],'child_process']])for(const k of keys)wrap(o,k,prefix+'.'+k);
globalThis.fetch=async()=>{record('fetch');throw Error('Network blocked for Task11D regression')};if(globalThis.WebSocket)globalThis.WebSocket=deny('WebSocket');
for(const channel of ['undici:request:create','undici:client:beforeConnect','http.client.request.start'])dc.channel(channel).subscribe(()=>{record(channel);throw Error('Network blocked for Task11D regression')});syncBuiltinESMExports();
fs.appendFileSync(life,JSON.stringify({event:'loaded',pid:process.pid,entry:process.argv[1],phase:process.env.PELORA_ATTEMPT_PHASE})+'\n');process.on('exit',code=>fs.appendFileSync(life,JSON.stringify({event:'exit',pid:process.pid,entry:process.argv[1],phase:process.env.PELORA_ATTEMPT_PHASE,code,attempts:count})+'\n'));

