param([string]$CheckoutRoot,[string]$PlanJson,[string]$ReviewRoot,[switch]$FullRegression)
$ErrorActionPreference='Stop'
$p=Get-Content -LiteralPath $PlanJson -Raw|ConvertFrom-Json
if((node --version) -ne 'v24.18.0'){throw 'runtime'}
$phase=if($FullRegression){'full'}else{'focused'}
$preload=Join-Path $ReviewRoot 'block-network.mjs'
if((Get-FileHash $preload).Hash.ToLower() -ne $p.networkBlocking.sha256){throw 'preload'}
foreach($flag in $p.networkBlocking.generationFlagsToUnset){Remove-Item -LiteralPath ('Env:'+$flag) -ErrorAction SilentlyContinue}
$env:PELORA_TEST_OCEAN_CONDITIONS='1'
$env:PELORA_DENIAL_PRELOAD_URL=([Uri]::new($preload).AbsoluteUri)
$env:PELORA_ATTEMPT_LOG=Join-Path $ReviewRoot ($phase+'-attempts.jsonl')
$env:PELORA_LIFECYCLE_LOG=Join-Path $ReviewRoot ($phase+'-lifecycle.jsonl')
[IO.File]::WriteAllText($env:PELORA_ATTEMPT_LOG,'')
foreach($entry in $p.scratch|Where-Object kind -eq 'UNCONDITIONAL_TEST_OUTPUT'){New-Item -ItemType Directory -Force (Join-Path $CheckoutRoot $entry.directory)|Out-Null}
$g=$p.testExecutionPlan|Where-Object group -eq CP07
$tests=@($g.focused)+@($g.dependencyAndCritical)
if($FullRegression){foreach($e in $p.offlineRetainedInputs){if((Get-FileHash (Join-Path $CheckoutRoot $e.path)).Hash.ToLower() -ne $e.sha256){throw 'retained'}};$tests=@(Get-ChildItem -LiteralPath (Join-Path $CheckoutRoot 'backend/tests'),(Join-Path $CheckoutRoot 'shared') -Recurse -File|Where-Object {$_.Name -like '*.test.js' -and $_.Name -ne 'candidateSemanticProjectionV3.test.js'}|ForEach-Object {[IO.Path]::GetRelativePath($CheckoutRoot,$_.FullName)})}
$tests=@($tests|Where-Object {$_}|Sort-Object -Unique)
if($tests|Where-Object {$_ -match 'candidateSemanticProjectionV3'}){throw 'V3 selection'}
$tests|ConvertTo-Json|Set-Content (Join-Path $ReviewRoot ($phase+'-intended.json'))
$logdir=Join-Path $ReviewRoot ($phase+'-logs');New-Item -ItemType Directory $logdir|Out-Null
$receipts=Join-Path $ReviewRoot ($phase+'-results.jsonl')
Push-Location $CheckoutRoot
try{foreach($file in $tests){$env:PELORA_ATTEMPT_PHASE=$phase+':'+$file;$name=($file -replace '[\\/]','_')+'.log'; @{event='start';file=$file;phase=$phase}|ConvertTo-Json -Compress|Add-Content $receipts; & node --import $env:PELORA_DENIAL_PRELOAD_URL --import ([Uri]::new((Join-Path $ReviewRoot 'attempt-monitor.mjs')).AbsoluteUri) $file *> (Join-Path $logdir $name); $code=$LASTEXITCODE; @{event='complete';file=$file;phase=$phase;exit=$code;log=$name}|ConvertTo-Json -Compress|Add-Content $receipts; if((Get-Item $env:PELORA_ATTEMPT_LOG).Length){throw ('NETWORK ATTEMPT '+$file)}; if($code){throw ('test '+$file)}; Write-Output ('PASS '+$file)}}finally{Pop-Location}
[IO.File]::WriteAllText((Join-Path $ReviewRoot ($phase+'-passed.txt')),'PASS')
